VALUES ('01a21950-32e4-74ec-9d6f-3eb593ed90a4', 'Treadmill', '["LEGS"]'::jsonb, '["CORE"]'::jsonb, 'Walking, jogging or running on a treadmill. An easy way to warm up or add steady cardio, and you can set the pace and incline exactly.', '["Step onto the side rails and start the belt at a slow walk", "Step onto the belt and walk for a few minutes to warm up", "Raise the speed or incline to your working pace", "Keep an upright posture and land under your hips", "Slow down for the last few minutes before stopping"]'::jsonb, '["Don''t hold the handrails while walking; it takes work off your legs", "Incline walking is a joint-friendly alternative to running", "Use the safety clip if your treadmill has one"]'::jsonb, 'BEGINNER', '["MACHINE"]'::jsonb, 'CARDIO', 'COMPOUND', 'DISTANCE_DURATION', NULL, NULL, 'DEFAULT', NULL, NULL, FALSE, 0, NULL, 0);

