VALUES ('01a21950-32e5-7c61-b0d6-309e78002c0f', 'Stationary Bike', '["LEGS"]'::jsonb, '[]'::jsonb, 'Steady cycling on a stationary bike. Low impact on the knees and hips, good for warm-ups, cardio sessions and recovery days.', '["Set the seat so your knee is slightly bent at the bottom of the pedal stroke", "Start pedalling at an easy resistance to warm up", "Raise the resistance to your working level", "Keep your upper body relaxed and your core steady", "Ease off for the last few minutes before stopping"]'::jsonb, '["A seat that is too low strains the knees", "Push and pull through the whole pedal circle", "Short harder intervals are a good way to add intensity"]'::jsonb, 'BEGINNER', '["MACHINE"]'::jsonb, 'CARDIO', 'COMPOUND', 'DURATION', NULL, NULL, 'DEFAULT', NULL, NULL, FALSE, 0, NULL, 0);

