VALUES ('01a21950-32e6-7778-8d8a-753887d1eebd', 'Stair Climber', '["LEGS"]'::jsonb, '["CORE"]'::jsonb, 'Climbing steps on a stair machine. Hard cardio that also works the glutes and quads.', '["Step on and hold the rails lightly for balance", "Start at a slow step speed to warm up", "Raise the speed to your working pace", "Push through the whole foot on each step", "Slow down for the last minute before stepping off"]'::jsonb, '["Don''t lean on the rails; stand tall and let your legs do the work", "Take full steps rather than short, quick ones", "Start with short sessions; it gets hard quickly"]'::jsonb, 'BEGINNER', '["MACHINE"]'::jsonb, 'CARDIO', 'COMPOUND', 'DURATION', NULL, NULL, 'DEFAULT', NULL, NULL, FALSE, 0, NULL, 0);

