VALUES ('01a21950-32e7-76b1-a8df-6857c433b47c', 'Machine Chest Press', '["CHEST"]'::jsonb, '["SHOULDERS", "ARMS"]'::jsonb, 'A seated pressing machine for the chest. The fixed path makes it a safe way to learn pressing and to train hard without a spotter.', '["Set the seat so the handles are level with your mid-chest", "Sit with your back flat against the pad and grip the handles", "Press the handles forward until your arms are almost straight", "Return slowly until you feel a stretch in your chest", "Repeat for the planned reps"]'::jsonb, '["Keep your shoulder blades pulled back against the pad", "Don''t lock your elbows hard at the top", "Control the way back; don''t let the stack slam"]'::jsonb, 'BEGINNER', '["MACHINE"]'::jsonb, 'STRENGTH', 'COMPOUND', 'WEIGHT_REPS', NULL, NULL, 'DEFAULT', NULL, NULL, FALSE, 0, NULL, 0);

