VALUES ('01a21950-32e8-7f58-8b7c-8bcb203677e7', 'Assisted Pull-Up', '["BACK"]'::jsonb, '["ARMS"]'::jsonb, 'A pull-up on an assisted machine or with a band, where the support takes part of your body weight. The way to build up to full pull-ups.', '["Set the assistance weight (more weight means more help)", "Kneel or stand on the platform and grip the bar wider than your shoulders", "Pull your chest up toward the bar", "Lower yourself slowly until your arms are straight", "Repeat for the planned reps"]'::jsonb, '["Use less assistance as you get stronger", "Start each rep by pulling your shoulders down", "Avoid swinging or kicking"]'::jsonb, 'BEGINNER', '["MACHINE"]'::jsonb, 'STRENGTH', 'COMPOUND', 'WEIGHT_REPS', NULL, NULL, 'DEFAULT', NULL, NULL, FALSE, 0, NULL, 0);

