VALUES ('01a21950-32e9-7e5d-a320-cf446713ea86', 'Dumbbell Romanian Deadlift', '["LEGS"]'::jsonb, '["BACK"]'::jsonb, 'A hip hinge with dumbbells that trains the hamstrings and glutes. Easier to learn than the barbell version.', '["Stand holding a dumbbell in each hand in front of your thighs", "Unlock your knees slightly", "Push your hips back and lower the dumbbells along your legs", "Stop when you feel a strong stretch in your hamstrings", "Drive your hips forward to stand back up"]'::jsonb, '["Keep your back flat the whole time", "Keep the dumbbells close to your legs", "Your knees stay soft but barely bend further"]'::jsonb, 'BEGINNER', '["DUMBBELL"]'::jsonb, 'STRENGTH', 'COMPOUND', 'WEIGHT_REPS', NULL, NULL, 'DEFAULT', NULL, NULL, FALSE, 0, NULL, 0);

