VALUES ('01a21950-32ea-712e-9979-d82407e6aa8c', 'Hip Abduction Machine', '["LEGS"]'::jsonb, '[]'::jsonb, 'A seated machine that pushes the legs apart to train the outer glutes. Helps hip stability for squats and lunges.', '["Sit with your back against the pad and the pads on the outside of your knees", "Set the start position so your legs are together", "Push your knees outward as far as you comfortably can", "Pause briefly, then return slowly", "Repeat for the planned reps"]'::jsonb, '["Control the return; don''t let the weights slam", "Leaning slightly forward shifts more work to the glutes", "Use a weight you can move without rocking"]'::jsonb, 'BEGINNER', '["MACHINE"]'::jsonb, 'STRENGTH', 'ISOLATION', 'WEIGHT_REPS', NULL, NULL, 'DEFAULT', NULL, NULL, FALSE, 0, NULL, 0);

