VALUES ('01a21950-32eb-74f9-b6d7-7e53e92b742a', 'Seated Leg Curl', '["LEGS"]'::jsonb, '[]'::jsonb, 'A seated machine curl for the hamstrings. The seated position stretches the hamstrings more than the lying version.', '["Sit with the back of your lower legs on the pad and the thigh pad snug", "Grip the handles and keep your back against the seat", "Curl your heels down and back as far as you can", "Pause briefly, then return slowly", "Repeat for the planned reps"]'::jsonb, '["Line up your knees with the machine''s pivot", "Don''t let your hips lift off the seat", "Control the way up"]'::jsonb, 'BEGINNER', '["MACHINE"]'::jsonb, 'STRENGTH', 'ISOLATION', 'WEIGHT_REPS', NULL, NULL, 'DEFAULT', NULL, NULL, FALSE, 0, NULL, 0);

