VALUES ('01a21950-32ec-7341-91cf-ef31d3cdb1a6', 'Glute Bridge', '["LEGS"]'::jsonb, '["CORE"]'::jsonb, 'A floor exercise that lifts the hips to train the glutes. A beginner-friendly version of the hip thrust; add weight on the hips as you get stronger.', '["Lie on your back with knees bent and feet flat, hip-width apart", "Brace your core and press through your heels", "Lift your hips until your body is straight from knees to shoulders", "Squeeze your glutes at the top for a moment", "Lower your hips slowly to the floor"]'::jsonb, '["Push through your heels, not your toes", "Don''t arch your lower back at the top", "Add a dumbbell or plate on your hips to progress"]'::jsonb, 'BEGINNER', '["BODYWEIGHT"]'::jsonb, 'STRENGTH', 'ISOLATION', 'WEIGHT_REPS', NULL, NULL, 'DEFAULT', NULL, NULL, FALSE, 0, NULL, 0);

